<script setup lang="ts">
const api = useApi(), data = ref<any>(null), error = ref(''), loading = ref(false)
const game = ref(''), set = ref(''), mode = ref('ambiguous'), page = ref(1), sets = ref<any[]>([])
let sequence = 0
const visibleSets = computed(() => sets.value.filter(s => !game.value || s.game === game.value))
async function load() {
  const request = ++sequence; loading.value = true; error.value = ''
  try { const result = await api('/api/catalogue/distribution-review', { query: { game: game.value, set: set.value, mode: mode.value, page: page.value } }); if (request === sequence) data.value = result }
  catch (e) { if (request === sequence) error.value = errorMessage(e) }
  finally { if (request === sequence) loading.value = false }
}
watch(game, () => { set.value = '' })
watch([game, set, mode], () => { page.value = 1; load() })
watch(page, load)
onMounted(async () => { load(); try { sets.value = (await api('/api/catalogue/facets')).sets } catch (e) { error.value = errorMessage(e) } })
onBeforeUnmount(() => { sequence++ })
</script>
<template><header class="page-heading"><div><span class="eyebrow">CATALOGUE QUALITY</span><h1>Printing distribution</h1><p>Review uncertain variants across every imported set.</p></div></header><p class="data-note">Three variants are a review hint, not proof of a promo. Compare the exact finish, language and product listing. Verified corrections survive re-imports and apply to regular-set binder completion.</p><div class="form-columns"><GamePicker v-model="game" all /><label>Set<select v-model="set"><option value="">All imported sets</option><option v-for="s in visibleSets" :key="s.id" :value="s.id">{{ s.name }} · {{ s.language.toUpperCase() }}</option></select></label><label>Review<select v-model="mode"><option value="ambiguous">3+ variants with unconfirmed distribution</option><option value="unknown">All unconfirmed distribution</option></select></label></div><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="loading" class="loading-panel">Loading printings…</p><template v-if="data"><p class="muted small">{{ data.total }} cards to review</p><article v-for="card in data.items" :key="card.id" class="panel distribution-review-card"><h2>{{ card.name }} · #{{ card.local_id }}</h2><p class="muted small">{{ card.set_name }} · {{ card.language.toUpperCase() }}</p><section v-for="p in card.printings" :key="p.id"><h3>{{ p.label }} <PrintingDistributionBadge :printing="p" /></h3><p v-if="p.distribution_note" class="small">{{ p.distribution_note }} <a v-if="p.distribution_url" :href="p.distribution_url" target="_blank" rel="noopener noreferrer">Source</a></p><p v-for="(signal, i) in p.distribution_signals" :key="i" class="data-note">Provider details: {{ [signal.finish, signal.subtype, signal.foil, signal.size, ...signal.stamps].filter(Boolean).join(' · ') }} <a v-if="signal.tcgplayer" :href="'https://www.tcgplayer.com/product/' + signal.tcgplayer" target="_blank" rel="noopener noreferrer">TCGplayer #{{ signal.tcgplayer }}</a><span v-if="signal.cardmarket"> · Cardmarket #{{ signal.cardmarket }}</span></p><PrintingDistributionEditor :card-id="card.id" :printing="p" :disabled="loading" @saved="load" /></section></article><p v-if="!data.items.length && !loading" class="empty-state">No cards match this review filter.</p><nav v-if="data.total > data.limit" class="pagination" aria-label="Distribution review pages"><button class="button secondary" :disabled="loading || page === 1" @click="page--">Previous</button><span>Page {{ page }}</span><button class="button secondary" :disabled="loading || page * data.limit >= data.total" @click="page++">Next</button></nav></template></template>
<style scoped>.distribution-review-card{padding:20px;margin:20px 0}.distribution-review-card h2{font-size:20px}.distribution-review-card h3{font-size:15px}.distribution-review-card section{padding-top:12px;border-top:1px solid var(--line);margin-top:16px}.distribution-review-card a{overflow-wrap:anywhere}</style>
